import {scanDuplicates,decidePair} from './duplicates-engine.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createDuplicateUI({getDocs,update,log,onImport}){const root=document.createElement('section');root.id='duplicates-page';root.hidden=true;document.querySelector('.content').insertBefore(root,document.querySelector('footer'));
 function render(){const docs=getDocs(),pairs=scanDuplicates(docs);root.innerHTML=`<section class="panel"><div class="panel-heading"><div><h2>${pairs.length} suspected duplicate pair${pairs.length===1?'':'s'}</h2><p>All queued and completed documents are checked together, including invoices and receipts. No automatic deletions.</p></div><button id="rescan" class="button primary">Rescan entire queue</button></div><div class="resolution-body"><p>Supplier + amount alone never triggers a match. Distinct invoice references are preserved unless file fingerprints prove identical content.</p><label class="draft-label" for="duplicate-upload">Add invoices or receipts to this queue</label><input id="duplicate-upload" type="file" multiple accept=".txt,.json,.pdf,.png,.jpg,.jpeg,.webp"><p class="hint">Batch uploads are added to the same queue and rechecked after each document finishes. PDF/image fields need review.</p><button id="duplicate-examples" class="button secondary">Add resilience examples</button><p class="hint">Adds a normalized supplier/reference pair, a missing-reference receipt, and a legitimate same-amount invoice.</p></div></section><div id="duplicate-status" role="status"></div><div class="duplicate-cards">${pairs.map(p=>`<article class="panel duplicate-card"><div class="panel-heading"><h2>${esc(p.level)}</h2><span class="payment-hold">HUMAN REVIEW</span></div><div class="resolution-body"><ul>${p.evidence.map(e=>`<li>${esc(e)}</li>`).join('')}</ul><div class="pair-documents">${[p.a,p.b].map(id=>{const d=docs.find(x=>x.id===id);return `<section class="source-card"><strong>${esc(d.fields.vendor)}</strong><p>${esc(d.fields.number||'Missing reference')} · $${Number(d.fields.total||0).toFixed(2)} · ${esc(d.documentType||'invoice')} · ${esc(d.status)}</p><details><summary>Inspect source evidence</summary><pre>${esc(d.source)}</pre></details></section>`;}).join('')}</div><form data-pair="${esc(p.key)}"><label>Decision reason<input name="reason" required placeholder="Explain what you verified"></label><label>Document to retain if duplicate<select name="keeper">${[p.a,p.b].map(id=>{const d=docs.find(x=>x.id===id);return `<option value="${esc(id)}">${esc(d.fields.number||'Missing reference')} — ${esc(d.name)}</option>`;}).join('')}</select></label><div class="actions"><button class="button secondary" name="decision" value="distinct">These are distinct</button><button class="button primary" name="decision" value="duplicate">Confirm duplicate</button></div></form></div></article>`).join('')||'<p class="empty">No unresolved duplicate candidates. Same-amount invoices with distinct references remain separate.</p>'}</div><section class="panel"><div class="panel-heading"><h2>Recorded decisions</h2></div>${[...new Map(docs.flatMap(d=>Object.entries(d.duplicateDecisions||{})).map(([k,v])=>[k,v])).values()].map(v=>`<div class="activity-item">${esc(v.action==='distinct'?'Kept as distinct':'Duplicate excluded from export')} · ${esc(v.note)}<small>${esc(v.at)} · Decisions are rechecked if document evidence changes.</small></div>`).join('')||'<p class="empty">No decisions yet.</p>'}</section>`;
 root.querySelector('#duplicate-upload').onchange=e=>onImport([...e.target.files]);
 root.querySelector('#rescan').onclick=()=>{update(getDocs());log('Rescanned the entire invoice queue for duplicates.');render();root.querySelector('#duplicate-status').textContent='Rescan complete, including documents already processed.';};
 root.querySelector('#duplicate-examples').onclick=()=>{if(getDocs().some(d=>d.id==='resilience-base'))return;const source='Vendor: Cedar Supply Co.\nInvoice: REF 123\nDue: 2026-12-20\nOffice shelving hardware delivery order number 8421 twelve metal brackets and six mounting plates\nSubtotal: 400.00\nTax: 0.00\nTotal: 400.00';const base={id:'resilience-base',name:'Original Cedar invoice',file:'cedar.txt',source,fields:{vendor:'Cedar Supply Co.',number:'REF 123',due:'2026-12-20',subtotal:400,tax:0,total:400},status:'queued'};update([...getDocs(),base,{...structuredClone(base),id:'resilience-copy',name:'Supplier name/reference variation',fields:{...base.fields,vendor:'CEDAR SUPPLY LLC',number:'123'}},{...structuredClone(base),id:'resilience-receipt',name:'Receipt with missing reference',documentType:'receipt',fields:{...base.fields,number:''}},{...structuredClone(base),id:'resilience-legitimate',name:'Separate legitimate invoice',source:source.replace('REF 123','124').replace('8421','8422'),fields:{...base.fields,number:'124'}}]);log('Added four duplicate-resilience examples.');render();};
 root.querySelectorAll('[data-pair]').forEach(form=>form.onsubmit=e=>{e.preventDefault();try{const f=new FormData(form);update(decidePair(getDocs(),form.dataset.pair,e.submitter.value,f.get('keeper'),f.get('reason')));log(`Duplicate review: ${e.submitter.value}; ${f.get('reason')}`);render();}catch(err){root.querySelector('#duplicate-status').textContent=err.message;}});
 }return {render};}
